  readonly projectCount: number;
  /** `null` while the workspace is writable; the shell banner reads this. */
  readonly lockReason: WorkspaceLockReason | null;
}

/**
 * Workspace read-only rule. A subscription that is not in good standing locks
 * member writes; reads, billing changes and Taskflow's own jobs do not consult
 * this module.
 */
import { parseIso } from "@/lib/date";
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(lockReasonMessage(reason));
    this.name = "WorkspaceLockedError";
  }
}

/** User-facing explanation of a lock, shared by the error and the shell banner. */
export function lockReasonMessage(reason: WorkspaceLockReason): string {
  switch (reason) {
    case "past_due":
      return "This workspace is read-only because the subscription is past due.";
    case "canceled":
      return "This workspace is read-only because the subscription is canceled.";
    case "trial_ended":
      return "This workspace is read-only because the trial has ended.";
  }
}

/**
 * The pure lock rule, evaluated against the subscription as stored at `now`
 * (defaulting to the current time).
 *
 * No subscription row, or an `active` subscription, is writable. `past_due` is
 * locked immediately. A trial locks at its period end. A cancellation locks
 * when its cancellation date is reached; a date still in the future stays
 * writable, and a canceled row with no date is locked now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      return subscription.cancelAt === null || reached(subscription.cancelAt, now)
        ? "canceled"
        : null;
  }
}

/** True once `stamp` is the current instant or in the past. */
function reached(stamp: NonNullable<Subscription["cancelAt"]>, now: Date): boolean {
  return now.getTime() >= parseIso(stamp).getTime();
}

