/**
 * Refuses a member write while the workspace subscription is not in good
 * standing. Billing changes, reads and Taskflow's own jobs do not call this.
 * `now` defaults to the current time so a trial or cancellation is judged at
 * the moment of the write.
 */
export async function assertWorkspaceWritable(
  orgId: OrgId,
  now: Date = new Date(),
): Promise<void> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
