pnpm exec tsx -e '
import { lockReasonFor } from "./src/lib/billing-lock.ts";
import type { Subscription } from "./src/types/billing.ts";
import type { IsoTimestamp, OrgId, SubscriptionId } from "./src/types/common.ts";

const now = new Date("2026-10-01T00:00:00.000Z");
const stamp = (s: string) => s as IsoTimestamp;
const base = {
  id: "sub" as SubscriptionId,
  orgId: "org" as OrgId,
  plan: "growth" as const,
  interval: "monthly" as const,
  seats: 3,
  currentPeriodStart: stamp("2026-09-01T00:00:00.000Z"),
  currentPeriodEnd: stamp("2026-10-15T00:00:00.000Z"),
  cancelAt: null,
  createdAt: stamp("2026-09-01T00:00:00.000Z"),
  updatedAt: stamp("2026-09-01T00:00:00.000Z"),
};

function sub(over: Partial<Subscription>): Subscription {
  return { ...base, status: "active", ...over };
}

const cases: [string, Subscription | null, string | null][] = [
  ["null", null, null],
  ["active", sub({ status: "active" }), null],
  ["active past period", sub({ status: "active", currentPeriodEnd: stamp("2026-09-01T00:00:00.000Z") }), null],
  ["past_due", sub({ status: "past_due" }), "past_due"],
  ["trial future", sub({ status: "trialing" }), null],
  ["trial at end", sub({ status: "trialing", currentPeriodEnd: stamp("2026-10-01T00:00:00.000Z") }), "trial_ended"],
  ["trial after", sub({ status: "trialing", currentPeriodEnd: stamp("2026-09-30T00:00:00.000Z") }), "trial_ended"],
  ["cancel future", sub({ status: "canceled", cancelAt: stamp("2026-10-15T00:00:00.000Z") }), null],
  ["cancel at now", sub({ status: "canceled", cancelAt: stamp("2026-10-01T00:00:00.000Z") }), "canceled"],
  ["cancel past", sub({ status: "canceled", cancelAt: stamp("2026-09-01T00:00:00.000Z") }), "canceled"],
  ["cancel null date", sub({ status: "canceled", cancelAt: null }), "canceled"],
];

let failed = 0;
for (const [name, subscription, expected] of cases) {
  const got = lockReasonFor(subscription, now);
  if (got !== expected) {
    console.log("FAIL", name, "got", got, "expected", expected);
    failed++;
  } else {
    console.log("ok", name);
  }
}
if (failed) process.exit(1);
